#!/usr/bin/env node
/**
 * Builds the minimal anime.js runtime that Motion's anime exporter inlines
 * into animated SVG files (ticket MM45 decision 9), and writes it as string
 * constants to `lib/vector/export/animeRuntime.generated.ts` (checked in,
 * "DO NOT EDIT").
 *
 *   - Entry: only `createTimeline`, `cubicBezier` and `steps` from the
 *     installed `animejs` ESM build; esbuild tree-shakes everything else
 *     (draggable, scroll, text, layout, WAAPI, svg helpers…).
 *   - Output: a minified IIFE assigning `var __mmAnime`, preceded by the
 *     package's own bundle header comment VERBATIM (version, licence,
 *     copyright), outside the minified block so minification can never drop it.
 *   - The package's LICENSE.md text is exported verbatim too: the exporter
 *     writes it as the file's first comment.
 *
 *   node scripts/gen-anime-runtime.mjs           (write)
 *   node scripts/gen-anime-runtime.mjs --check   (exit 1 when stale)
 *
 * `lib/vector/export/animeRuntime.test.ts` regenerates in memory and fails
 * when the checked-in file differs (a version bump without a regeneration).
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

export const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
export const OUT_FILE = join(ROOT, 'lib', 'vector', 'export', 'animeRuntime.generated.ts');
/** The anime.js API the generated player uses: nothing else is bundled. */
export const RUNTIME_EXPORTS = ['createTimeline', 'cubicBezier', 'steps'];
export const GLOBAL_NAME = '__mmAnime';

/** The source file text, pure given its inputs (used by the staleness test). */
export async function render(root = ROOT) {
  const { build } = await import('esbuild');
  const pkgDir = join(root, 'node_modules', 'animejs');
  const pkg = JSON.parse(readFileSync(join(pkgDir, 'package.json'), 'utf8'));
  const license = readFileSync(join(pkgDir, 'LICENSE.md'), 'utf8').replace(/\r\n/g, '\n').trim();
  const bundle = readFileSync(join(pkgDir, 'dist', 'bundles', 'anime.esm.min.js'), 'utf8');
  const header = /^\/\*\*[\s\S]*?\*\//.exec(bundle);
  if (!header) throw new Error('animejs bundle header comment not found');
  if (pkg.license !== 'MIT') throw new Error(`animejs licence is ${pkg.license}, not MIT`);
  const result = await build({
    stdin: { contents: `export { ${RUNTIME_EXPORTS.join(', ')} } from 'animejs';`, resolveDir: root, loader: 'js' },
    bundle: true,
    minify: true,
    format: 'iife',
    globalName: GLOBAL_NAME,
    legalComments: 'none',
    target: 'es2018',
    platform: 'browser',
    write: false,
    absWorkingDir: root,
  });
  const code = result.outputFiles[0].text.trim();
  const runtime = `${header[0]}\n${code}`;
  if (runtime.includes(']]>') || /<\/script/i.test(runtime)) throw new Error('runtime contains ]]> or </script');
  if (license.includes('--')) throw new Error('licence text contains "--" (not allowed in an XML comment)');
  return [
    '// DO NOT EDIT. Generated by scripts/gen-anime-runtime.mjs from the installed animejs package.',
    '// Regenerate after changing the pinned animejs version: node scripts/gen-anime-runtime.mjs',
    '',
    '/** The pinned animejs version (package.json, exact). */',
    `export const ANIME_VERSION = ${JSON.stringify(pkg.version)};`,
    '',
    '/** animejs LICENSE.md, verbatim (MIT). */',
    `export const ANIME_LICENSE = ${JSON.stringify(license)};`,
    '',
    `/** The anime.js API in the runtime (${RUNTIME_EXPORTS.join(', ')}), exposed as \`var ${GLOBAL_NAME}\`. */`,
    `export const ANIME_RUNTIME_EXPORTS = ${JSON.stringify(RUNTIME_EXPORTS)} as const;`,
    '',
    `/** Minified IIFE (\`var ${GLOBAL_NAME} = …\`) after the package's bundle header comment, verbatim. */`,
    `export const ANIME_RUNTIME = ${JSON.stringify(runtime)};`,
    '',
  ].join('\n');
}

async function main() {
  const text = await render();
  if (process.argv.includes('--check')) {
    let current = '';
    try {
      current = readFileSync(OUT_FILE, 'utf8');
    } catch {
      /* missing */
    }
    if (current !== text) {
      console.error(`${OUT_FILE} is stale — run node scripts/gen-anime-runtime.mjs`);
      process.exit(1);
    }
    console.log('anime runtime up to date');
    return;
  }
  writeFileSync(OUT_FILE, text);
  const runtime = /export const ANIME_RUNTIME = (".*");/.exec(text)[1];
  console.log(`wrote ${OUT_FILE} (${JSON.parse(runtime).length} bytes runtime)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main().catch((e) => {
    console.error(e);
    process.exit(1);
  });
}
